require_once __DIR__.'/../config/security.php';start_secure_session();require_once __DIR__.'/../config/database.php';
if(($_SESSION['role']??'')!=='dentist'){header('Location: ../auth/login.php');exit;}
$uid=(int)$_SESSION['user_id'];$msg='';$type='success';$statuses=['new','reviewed','scheduled','resolved'];$teeth=['18','17','16','15','14','13','12','11','21','22','23','24','25','26','27','28','48','47','46','45','44','43','42','41','31','32','33','34','35','36','37','38'];$concerns=['Pain / Toothache','Sensitivity to hot or cold','Broken / Chipped tooth','Loose tooth','Swelling / Gum concern','Possible cavity / dark spot','Extraction concern - needs dentist evaluation','Other concern'];
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$tooth=trim($_POST['tooth_number']??'');$concern=trim($_POST['concern_type']??'');$severity=(int)($_POST['severity']??1);$status=trim($_POST['status']??'');$note=trim($_POST['staff_note']??'');if(!csrf_valid($_POST['csrf_token']??null)){$msg='Session expired. Refresh and try again.';$type='error';}elseif($id<1||!in_array($tooth,$teeth,true)||!in_array($concern,$concerns,true)||$severity<1||$severity>10||!in_array($status,$statuses,true)||mb_strlen($note)>1500){$msg='Invalid update.';$type='error';}else{$st=$conn->prepare('UPDATE patient_tooth_reports SET tooth_number=?,concern_type=?,severity=?,status=?,staff_note=?,reviewed_by=? WHERE id=?');$st->bind_param('ssissii',$tooth,$concern,$severity,$status,$note,$uid,$id);$st->execute();$st->close();$msg='Patient concern updated.';log_activity($conn,$uid,'Reviewed tooth concern','Patient Concerns','Report #'.$id);}}
$rows=[];$r=$conn->query("SELECT r.*,u.first_name,u.last_name,u.email FROM patient_tooth_reports r JOIN users u ON u.id=r.patient_id ORDER BY FIELD(r.status,'new','reviewed','scheduled','resolved'),r.created_at DESC LIMIT 100");if($r)while($x=$r->fetch_assoc())$rows[]=$x;
require '../includes/ui.php';ui_header('Patient Concerns','dentist');ui_sidebar('dentist','tooth_concerns.php');
?>
<div class="page-head"><div><div class="eyebrow">PATIENT-REPORTED 3D CONCERNS</div><h1>Patient Tooth Concerns</h1><div class="muted">Review the tooth selected by the patient, correct the report if needed, and add a clinical workflow note.</div></div><a class="btn btn-secondary" href="appointments.php"><i class="fa-solid fa-calendar-days"></i> Appointments</a></div>
<?php if($msg)flash($type,$msg);?>
<section class="card"><div class="card-heading"><div><h2>Concern Queue</h2><p class="muted">These are patient-reported symptoms, not confirmed diagnoses.</p></div><span class="badge"><?=count($rows)?> reports</span></div><div class="concern-history"><?php if(!$rows):?><div class="empty">No patient concerns submitted yet.</div><?php endif;?><?php foreach($rows as $r):?><article class="concern-item"><div class="concern-item-top"><div class="report-patient"><span class="report-patient-avatar"><?=e(strtoupper(substr($r['first_name'],0,1)))?></span><div><b><?=e($r['first_name'].' '.$r['last_name'])?></b><div class="muted"><?=e($r['email'])?> · <?=e(date('M d, Y h:i A',strtotime($r['created_at'])))?></div></div></div><span class="badge"><?=e(ucfirst($r['status']))?></span></div><?php if($r['notes']):?><p class="muted"><b>Patient note:</b> <?=nl2br(e($r['notes']))?></p><?php endif;?><form method="post" class="staff-edit-grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><div class="field"><label>Tooth</label><select name="tooth_number"><?php foreach($teeth as $t):?><option value="<?=$t?>" <?=$r['tooth_number']===$t?'selected':''?>><?=$t?></option><?php endforeach;?></select></div><div class="field"><label>Concern</label><select name="concern_type"><?php foreach($concerns as $c):?><option value="<?=e($c)?>" <?=$r['concern_type']===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select></div><div class="field"><label>Severity</label><input type="number" name="severity" min="1" max="10" value="<?=e($r['severity'])?>"></div><div class="field"><label>Status</label><select name="status"><?php foreach($statuses as $s):?><option value="<?=$s?>" <?=$r['status']===$s?'selected':''?>><?=e(ucfirst($s))?></option><?php endforeach;?></select></div><div class="field wide"><label>Dentist note</label><textarea name="staff_note" maxlength="1500" placeholder="Clinical/workflow note"><?=e($r['staff_note'])?></textarea></div><div class="actions"><button class="btn btn-primary">Save Update</button></div></form><div style="margin-top:10px;display:flex;gap:8px;flex-wrap:wrap"><a class="btn btn-secondary" href="patient_view.php?id=<?=$r['patient_id']?>">View Patient</a><a class="btn btn-secondary" href="odontogram.php?patient_id=<?=$r['patient_id']?>">Open 3D Odontogram</a><a class="btn btn-secondary" href="chart_editor.php?patient_id=<?=$r['patient_id']?>">Create Chart</a></div></article><?php endforeach;?></div></section>
